 async function reload(){try{const [d,m,i]=await Promise.all([api('/dashboard'),api('/me'),api('/integrations')]);setData(d);setMe(m);setIntegrations(i);setAuthMode(m.mode);setError('');}catch(e){setError((e as Error).message)}}
 useEffect(()=>{api('/auth/config').then(v=>setAuthMode(v.mode)).catch(()=>{});reload()},[role]);
