 useEffect(()=>{if(!routeReady)return;let active=true;const endpoint:Record<string,string>={appraisal:'/approval-workbench/applications',origination:'/applications',documents:'/document-review/applications',financials:'/financial-spreading/applications',cashflow:'/cash-flow/applications',assignments:'/employee-assignments'};if(endpoint[nav])api(endpoint[nav]).then(applications=>{if(active)setData(d=>d?{...d,applications}:d)}).catch(e=>{if(active)setError(e.message)});return()=>{active=false}},[nav,role,routeReady]);
 useEffect(()=>{let active=true;const refresh=()=>{if(nav==='exceptions')api('/exceptions').then(value=>{if(active)setExceptions(value)}).catch(e=>{if(active)setError(e.message)});if(nav==='audit')api('/audit').then(value=>{if(active)setAudit(value)}).catch(e=>{if(active)setError(e.message)})};refresh();const timer=nav==='exceptions'?setInterval(refresh,5000):undefined;return()=>{active=false;if(timer)clearInterval(timer)}},[nav,role]);
 async function action(fn:()=>Promise<any>,message?:string){setBusy(true);setError('');try{await fn();if(message)notify(message)}catch(e){setError((e as Error).message)}finally{setBusy(false)}}
 const cases=useMemo(()=> (data?.applications||[]).filter((c:Data)=>(!query||`${c.borrower} ${c.reference} ${c.sector}`.toLowerCase().includes(query.toLowerCase()))&&(product==='all'||c.product===product)&&(status==='all'||(status==='awaiting_decision'?['pending_approval','in_review'].includes(c.status):c.status===status))&&(branch==='all'||c.branch===branch)).sort((a:Data,b:Data)=>nav==='appraisal'?(Number(b.status==='pending_approval')-Number(a.status==='pending_approval')||new Date(a.created_at).getTime()-new Date(b.created_at).getTime()):0),[data,query,product,status,branch,nav]);
 const requested=cases.reduce((s:number,c:Data)=>s+Number(c.amount),0),sanctioned=cases.reduce((s:number,c:Data)=>s+Number(c.sanctioned_amount||0),0),active=cases.filter((c:Data)=>!['approved','declined','withdrawn'].includes(c.status));
 const exceptions=(data?.exceptions||[]).filter((x:Data)=>cases.some((c:Data)=>c.id===x.application_id));
 function drill(stage='all'){enterDrilldown();setStatus(stage)}
 function exportCases(){const csv=['Reference,Borrower,Product,Requested INR,Sanctioned INR,Status,Branch',...cases.map((c:Data)=>[c.reference,c.borrower,c.product,c.amount,c.sanctioned_amount||'',c.status,c.branch].map(v=>'"'+String(v).replaceAll('"','""')+'"').join(','))].join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='credit-pipeline.csv';a.click();URL.revokeObjectURL(a.href)}
 async function runAssessment(){if(!detail)return;await action(async()=>{const j=await api(`/applications/${selected}/assessments`,{expected_version:detail.application.version});setJob(j);if(j.status==='failed')throw new Error(j.error);followJob(j.id,v=>{setJob(v);if(v.status==='completed'){refreshCase();notify('Assessment completed')}if(v.status==='failed')setError(v.error)}).catch(e=>setError(e.message))},'Assessment queued')}
